1	import { lazy, Suspense, useEffect } from "react";
2	import { Toaster as Sonner } from "@/components/ui/sonner";
3	import { TooltipProvider } from "@/components/ui/tooltip";
4	import { QueryClient, QueryClientProvider, useQueryClient } from "@tanstack/react-query";
5	import { BrowserRouter, Routes, Route } from "react-router-dom";
6	import { AuthProvider, useAuth } from "@/hooks/useAuth";
7	import { useFeatureFlag } from "@/hooks/useFeatureFlags";
8	import { ProtectedRoute, AdminRoute } from "@/components/ProtectedRoute";
9	import { ThemeProvider } from "@/components/ThemeProvider";
10	import MaintenancePage from "@/components/MaintenancePage";
11	import SeoHead from "@/components/SeoHead";
12	import ChatWidget from "@/components/ChatWidget";
13	import { supabase } from "@/integrations/supabase/client";
14	
15	// Eager imports — core pages users navigate between constantly (no Suspense flash)
16	import Index from "./pages/Index";
17	import Auth from "./pages/Auth";
18	import Settings from "./pages/Settings";
19	import Profile from "./pages/Profile";
20	import Billing from "./pages/Billing";
21	import Team from "./pages/Team";
22	import Tasks from "./pages/Tasks";
23	import Activity from "./pages/Activity";
24	
25	// Sidebar-accessible pages — eager to avoid flash on click
26	import Changelog from "./pages/Changelog";
27	import RequestFeature from "./pages/RequestFeature";
28	import CareerSettings from "./pages/CareerSettings";
29	import Integrations from "./pages/Integrations";
30	import ApiDocs from "./pages/ApiDocs";
31	import Reports from "./pages/Reports";
32	import AgencyHub from "./pages/AgencyHub";
33	import TalentPool from "./pages/TalentPool";
34	
35	// Lazy imports — infrequent or large pages
36	const Admin = lazy(() => import("./pages/Admin"));
37	const NotFound = lazy(() => import("./pages/NotFound"));
38	const PaymentCallback = lazy(() => import("./pages/PaymentCallback"));
39	const BookDemo = lazy(() => import("./pages/BookDemo"));
40	const Apply = lazy(() => import("./pages/Apply"));
41	const CareerPage = lazy(() => import("./pages/CareerPage"));
42	const CareerJobDetail = lazy(() => import("./pages/CareerJobDetail"));
43	const LandingPage = lazy(() => import("@/components/LandingPage"));
44	const SharedPortal = lazy(() => import("./pages/SharedPortal"));
45	const BookInterview = lazy(() => import("./pages/BookInterview"));
46	
47	const queryClient = new QueryClient({
48	  defaultOptions: {
49	    queries: {
50	      staleTime: 5 * 60 * 1000,
51	      gcTime: 10 * 60 * 1000,
52	      refetchOnWindowFocus: false,
53	      refetchOnMount: false,
54	      retry: 1,
55	    },
56	  },
57	});
58	
59	/** Full-width skeleton that matches the sidebar+content layout to prevent layout shift */
60	const PageLoader = () => (
61	  <div className="flex h-svh w-full overflow-hidden">
62	    {/* Sidebar skeleton — matches sidebar width */}
63	    <div className="hidden md:flex w-[var(--sidebar-width,16rem)] shrink-0 flex-col border-r border-border bg-sidebar">
64	      <div className="px-4 py-4">
65	        <div className="h-5 w-24 rounded bg-muted animate-pulse" />
66	      </div>
67	      <div className="border-t border-border" />
68	      <div className="p-3 space-y-2">
69	        {[1, 2, 3, 4].map((i) => (
70	          <div key={i} className="h-8 rounded-md bg-muted/50 animate-pulse" />
71	        ))}
72	      </div>
73	    </div>
74	    {/* Content area skeleton */}
75	    <div className="flex-1 flex flex-col min-w-0">
76	      {/* Header skeleton */}
77	      <div className="h-14 border-b border-border flex items-center justify-between px-4 shrink-0">
78	        <div className="h-4 w-20 rounded bg-muted animate-pulse" />
79	        <div className="flex items-center gap-3">
80	          <div className="h-8 w-8 rounded-lg bg-muted animate-pulse" />
81	          <div className="h-8 w-8 rounded-full bg-muted animate-pulse" />
82	        </div>
83	      </div>
84	      {/* Body skeleton */}
85	      <div className="flex-1 overflow-y-auto p-6">
86	        <div className="max-w-5xl mx-auto space-y-4">
87	          <div className="h-7 w-48 rounded bg-muted animate-pulse" />
88	          <div className="h-4 w-72 rounded bg-muted/60 animate-pulse" />
89	          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6">
90	            {[1, 2, 3, 4].map((i) => (
91	              <div key={i} className="h-20 rounded-xl border border-border bg-muted/30 animate-pulse" />
92	            ))}
93	          </div>
94	        </div>
95	      </div>
96	    </div>
97	  </div>
98	);
99	
100	const MaintenanceGate = ({ children }: { children: React.ReactNode }) => {
101	  const { enabled, isLoading: flagLoading } = useFeatureFlag("maintenance_mode");
102	  const { isAdmin, loading } = useAuth();
103	
104	  // Don't block rendering while loading — only gate when we know maintenance is on
105	  if (!loading && !flagLoading && enabled && !isAdmin) return <MaintenancePage />;
106	  return <>{children}</>;
107	};
108	
109	const RootRoute = () => {
110	  const { user, loading } = useAuth();
111	  if (loading) return <PageLoader />;
112	  return user ? <Index /> : <LandingPage />;
113	};
114	
115	/** Silently prefetches sidebar-linked pages so they open instantly on first click */
116	const DataPrefetcher = () => {
117	  const { user } = useAuth();
118	  const qc = useQueryClient();
119	
120	  useEffect(() => {
121	    // Prefetch public data that doesn't require auth
122	    qc.prefetchQuery({
123	      queryKey: ["changelog_public"],
124	      queryFn: async () => {
125	        const { data } = await (supabase as any)
126	          .from("changelog")
127	          .select("id, version, title, description, category, published_at")
128	          .eq("status", "published")
129	          .order("published_at", { ascending: false });
130	        return data ?? [];
131	      },
132	      staleTime: 5 * 60 * 1000,
133	    });
134	    qc.prefetchQuery({
135	      queryKey: ["feature_requests"],
136	      queryFn: async () => {
137	        const { data } = await (supabase as any)
138	          .from("feature_requests")
139	          .select("*")
140	          .order("created_at", { ascending: false });
141	        return data ?? [];
142	      },
143	      staleTime: 5 * 60 * 1000,
144	    });
145	  }, []);
146	
147	  useEffect(() => {
148	    if (!user) return;
149	    qc.prefetchQuery({
150	      queryKey: ["my_feature_votes"],
151	      queryFn: async () => {
152	        const { data } = await (supabase as any)
153	          .from("feature_request_votes")
154	          .select("feature_request_id")
155	          .eq("user_id", user.id);
156	        return (data ?? []).map((v: any) => v.feature_request_id);
157	      },
158	      staleTime: 5 * 60 * 1000,
159	    });
160	  }, [user?.id]);
161	
162	  return null;
163	};
164	
165	const App = () => (
166	  <QueryClientProvider client={queryClient}>
167	    <ThemeProvider attribute="class" defaultTheme="light" storageKey="rankora-theme">
168	      <AuthProvider>
169	        <DataPrefetcher />
170	        <TooltipProvider>
171	          <Sonner />
172	          <BrowserRouter>
173	            <SeoHead />
174	            <Suspense fallback={<PageLoader />}>
175	              <Routes>
176	                {/* Public pages — outside MaintenanceGate so candidates/guests can always access */}
177	                <Route path="/apply/:jobId" element={<Apply />} />
178	                <Route path="/careers/:slug" element={<CareerPage />} />
179	                <Route path="/careers/:slug/jobs/:jobId" element={<CareerJobDetail />} />
180	                <Route path="/shared/:token" element={<SharedPortal />} />
181	                <Route path="/book/:token" element={<BookInterview />} />
182	                <Route path="*" element={
183	                  <MaintenanceGate>
184	                    <Routes>
185	                      <Route path="/auth" element={<Auth />} />
186	                      <Route path="/" element={<RootRoute />} />
187	                      <Route path="/jobs" element={<ProtectedRoute><Index /></ProtectedRoute>} />
188	                      <Route path="/profile" element={<ProtectedRoute><Profile /></ProtectedRoute>} />
189	                      <Route path="/billing" element={<ProtectedRoute><Billing /></ProtectedRoute>} />
190	                      <Route path="/settings" element={<ProtectedRoute><Settings /></ProtectedRoute>} />
191	                      <Route path="/team" element={<ProtectedRoute><Team /></ProtectedRoute>} />
192	                      <Route path="/tasks" element={<ProtectedRoute><Tasks /></ProtectedRoute>} />
193	                      <Route path="/activity" element={<ProtectedRoute><Activity /></ProtectedRoute>} />
194	                      <Route path="/career-settings" element={<ProtectedRoute><CareerSettings /></ProtectedRoute>} />
195	                      <Route path="/integrations" element={<ProtectedRoute><Integrations /></ProtectedRoute>} />
196	                      <Route path="/api-docs" element={<ProtectedRoute><ApiDocs /></ProtectedRoute>} />
197	                      <Route path="/reports" element={<ProtectedRoute><Reports /></ProtectedRoute>} />
198	                      <Route path="/agency" element={<ProtectedRoute><AgencyHub /></ProtectedRoute>} />
199	                      <Route path="/talent-pool" element={<ProtectedRoute><TalentPool /></ProtectedRoute>} />
200	                      <Route path="/admin" element={<AdminRoute><Admin /></AdminRoute>} />
201	                      <Route path="/book-demo" element={<BookDemo />} />
202	                      <Route path="/request-feature" element={<RequestFeature />} />
203	                      <Route path="/changelog" element={<Changelog />} />
204	                      <Route path="/payment/callback" element={<PaymentCallback />} />
205	                      <Route path="*" element={<NotFound />} />
206	                    </Routes>
207	                  </MaintenanceGate>
208	                } />
209	              </Routes>
210	            </Suspense>
211	            <ChatWidget />
212	          </BrowserRouter>
213	        </TooltipProvider>
214	      </AuthProvider>
215	    </ThemeProvider>
216	  </QueryClientProvider>
217	);
218	
219	export default App;
